section.sourcecode:
struct sadb_msg {
        uint8_t sadb_msg_version;
        uint8_t sadb_msg_type;
        uint8_t sadb_msg_errno;
        uint8_t sadb_msg_satype;
        uint16_t sadb_msg_len;
        uint16_t sadb_msg_reserved;
        uint32_t sadb_msg_seq;
        uint32_t sadb_msg_pid;
};
/* sizeof(struct sadb_msg) == 16 */

struct sadb_ext {
        uint16_t sadb_ext_len;
        uint16_t sadb_ext_type;
};
/* sizeof(struct sadb_ext) == 4 */

struct sadb_sa {
        uint16_t sadb_sa_len;
        uint16_t sadb_sa_exttype;
        uint32_t sadb_sa_spi;
        uint8_t sadb_sa_replay;
        uint8_t sadb_sa_state;
        uint8_t sadb_sa_auth;
        uint8_t sadb_sa_encrypt;
        uint32_t sadb_sa_flags;
};

struct sadb_lifetime {
        uint16_t sadb_lifetime_len;
        uint16_t sadb_lifetime_exttype;
        uint32_t sadb_lifetime_allocations;
        uint64_t sadb_lifetime_bytes;
        uint64_t sadb_lifetime_addtime;
        uint64_t sadb_lifetime_usetime;
};
/* sizeof(struct sadb_lifetime) == 32 */

struct sadb_address {
        uint16_t sadb_address_len;
        uint16_t sadb_address_exttype;
        uint8_t sadb_address_proto;
        uint8_t sadb_address_prefixlen;
        uint16_t sadb_address_reserved;
};
/* sizeof(struct sadb_address) == 8 */

struct sadb_key {
        uint16_t sadb_key_len;
        uint16_t sadb_key_exttype;
        uint16_t sadb_key_bits;
        uint16_t sadb_key_reserved;
};
/* sizeof(struct sadb_key) == 8 */

struct sadb_ident {
        uint16_t sadb_ident_len;
        uint16_t sadb_ident_exttype;
        uint16_t sadb_ident_type;
        uint16_t sadb_ident_reserved;
        uint64_t sadb_ident_id;
};
/* sizeof(struct sadb_ident) == 16 */

struct sadb_sens {
        uint16_t sadb_sens_len;
        uint16_t sadb_sens_exttype;

        uint32_t sadb_sens_dpd;
        uint8_t sadb_sens_sens_level;
        uint8_t sadb_sens_sens_len;
        uint8_t sadb_sens_integ_level;
        uint8_t sadb_sens_integ_len;
        uint32_t sadb_sens_reserved;
};
/* sizeof(struct sadb_sens) == 16 */

/* この後に次のものが続く:
        uint64_t sadb_sens_bitmap[sens_len];
        uint64_t sadb_integ_bitmap[integ_len]; */

struct sadb_prop {
        uint16_t sadb_prop_len;
        uint16_t sadb_prop_exttype;
        uint8_t sadb_prop_replay;
        uint8_t sadb_prop_reserved[3];
};
/* sizeof(struct sadb_prop) == 8 */

struct sadb_comb {
        uint8_t sadb_comb_auth;
        uint8_t sadb_comb_encrypt;
        uint16_t sadb_comb_flags;
        uint16_t sadb_comb_auth_minbits;
        uint16_t sadb_comb_auth_maxbits;
        uint16_t sadb_comb_encrypt_minbits;
        uint16_t sadb_comb_encrypt_maxbits;
        uint32_t sadb_comb_reserved;
        uint32_t sadb_comb_soft_allocations;
        uint32_t sadb_comb_hard_allocations;
        uint64_t sadb_comb_soft_bytes;
        uint64_t sadb_comb_hard_bytes;
        uint64_t sadb_comb_soft_addtime;
        uint64_t sadb_comb_hard_addtime;
        uint64_t sadb_comb_soft_usetime;
        uint64_t sadb_comb_hard_usetime;
};

struct sadb_supported {
        uint16_t sadb_supported_len;
        uint16_t sadb_supported_exttype;
        uint32_t sadb_supported_reserved;
};
/* sizeof(struct sadb_supported) == 8 */

struct sadb_alg {
        uint8_t sadb_alg_id;
        uint8_t sadb_alg_ivlen;
        uint16_t sadb_alg_minbits;
        uint16_t sadb_alg_maxbits;
        uint16_t sadb_alg_reserved;
};
/* sizeof(struct sadb_alg) == 8 */

struct sadb_spirange {
        uint16_t sadb_spirange_len;
        uint16_t sadb_spirange_exttype;
        uint32_t sadb_spirange_min;
        uint32_t sadb_spirange_max;
        uint32_t sadb_spirange_reserved;
};
/* sizeof(struct sadb_spirange) == 16 */

struct sadb_x_kmprivate {
        uint16_t sadb_x_kmprivate_len;
        uint16_t sadb_x_kmprivate_exttype;
        uint32_t sadb_x_kmprivate_reserved;
};
/* sizeof(struct sadb_x_kmprivate) == 8 */

/*
このファイルは、PF_KEYバージョン2の鍵管理インターフェースのための構造体と
シンボルを定義する。これは米国海軍研究所（U.S. Naval Research
Laboratory）で書かれた。このファイルはパブリックドメインである。著者は、
このファイルのすべての複製でこのクレジットをそのまま残すよう求めている。
*/
#ifndef __PFKEY_V2_H
#define __PFKEY_V2_H 1

#define PF_KEY_V2 2
#define PFKEYV2_REVISION        199806L

#define SADB_RESERVED    0
#define SADB_GETSPI      1
#define SADB_UPDATE      2
#define SADB_ADD         3
#define SADB_DELETE      4
#define SADB_GET         5
#define SADB_ACQUIRE     6
#define SADB_REGISTER    7
#define SADB_EXPIRE      8
#define SADB_FLUSH       9
#define SADB_DUMP        10
#define SADB_X_PROMISC   11
#define SADB_X_PCHANGE   12
#define SADB_MAX         12

struct sadb_msg {
  uint8_t sadb_msg_version;
  uint8_t sadb_msg_type;
  uint8_t sadb_msg_errno;
  uint8_t sadb_msg_satype;
  uint16_t sadb_msg_len;
  uint16_t sadb_msg_reserved;
  uint32_t sadb_msg_seq;
  uint32_t sadb_msg_pid;
};

struct sadb_ext {
  uint16_t sadb_ext_len;
  uint16_t sadb_ext_type;
};

struct sadb_sa {
  uint16_t sadb_sa_len;
  uint16_t sadb_sa_exttype;
  uint32_t sadb_sa_spi;
  uint8_t sadb_sa_replay;
  uint8_t sadb_sa_state;
  uint8_t sadb_sa_auth;
  uint8_t sadb_sa_encrypt;
  uint32_t sadb_sa_flags;
};

struct sadb_lifetime {
  uint16_t sadb_lifetime_len;
  uint16_t sadb_lifetime_exttype;
  uint32_t sadb_lifetime_allocations;
  uint64_t sadb_lifetime_bytes;
  uint64_t sadb_lifetime_addtime;
  uint64_t sadb_lifetime_usetime;
};

struct sadb_address {
  uint16_t sadb_address_len;
  uint16_t sadb_address_exttype;
  uint8_t sadb_address_proto;
  uint8_t sadb_address_prefixlen;
  uint16_t sadb_address_reserved;
};

struct sadb_key {
  uint16_t sadb_key_len;
  uint16_t sadb_key_exttype;
  uint16_t sadb_key_bits;
  uint16_t sadb_key_reserved;
};

struct sadb_ident {
  uint16_t sadb_ident_len;
  uint16_t sadb_ident_exttype;
  uint16_t sadb_ident_type;
  uint16_t sadb_ident_reserved;
  uint64_t sadb_ident_id;
};

struct sadb_sens {
  uint16_t sadb_sens_len;
  uint16_t sadb_sens_exttype;
  uint32_t sadb_sens_dpd;
  uint8_t sadb_sens_sens_level;
  uint8_t sadb_sens_sens_len;
  uint8_t sadb_sens_integ_level;
  uint8_t sadb_sens_integ_len;
  uint32_t sadb_sens_reserved;
};

struct sadb_prop {
  uint16_t sadb_prop_len;
  uint16_t sadb_prop_exttype;
  uint8_t sadb_prop_replay;
  uint8_t sadb_prop_reserved[3];
};

struct sadb_comb {
  uint8_t sadb_comb_auth;
  uint8_t sadb_comb_encrypt;
  uint16_t sadb_comb_flags;
  uint16_t sadb_comb_auth_minbits;
  uint16_t sadb_comb_auth_maxbits;
  uint16_t sadb_comb_encrypt_minbits;
  uint16_t sadb_comb_encrypt_maxbits;
  uint32_t sadb_comb_reserved;
  uint32_t sadb_comb_soft_allocations;
  uint32_t sadb_comb_hard_allocations;
  uint64_t sadb_comb_soft_bytes;
  uint64_t sadb_comb_hard_bytes;
  uint64_t sadb_comb_soft_addtime;
  uint64_t sadb_comb_hard_addtime;
  uint64_t sadb_comb_soft_usetime;
  uint64_t sadb_comb_hard_usetime;
};

struct sadb_supported {
  uint16_t sadb_supported_len;
  uint16_t sadb_supported_exttype;
  uint32_t sadb_supported_reserved;
};

struct sadb_alg {
  uint8_t sadb_alg_id;
  uint8_t sadb_alg_ivlen;
  uint16_t sadb_alg_minbits;
  uint16_t sadb_alg_maxbits;
  uint16_t sadb_alg_reserved;
};

struct sadb_spirange {
  uint16_t sadb_spirange_len;
  uint16_t sadb_spirange_exttype;
  uint32_t sadb_spirange_min;
  uint32_t sadb_spirange_max;
  uint32_t sadb_spirange_reserved;
};

struct sadb_x_kmprivate {
  uint16_t sadb_x_kmprivate_len;
  uint16_t sadb_x_kmprivate_exttype;
  uint32_t sadb_x_kmprivate_reserved;
};

#define SADB_EXT_RESERVED             0
#define SADB_EXT_SA                   1
#define SADB_EXT_LIFETIME_CURRENT     2
#define SADB_EXT_LIFETIME_HARD        3
#define SADB_EXT_LIFETIME_SOFT        4
#define SADB_EXT_ADDRESS_SRC          5
#define SADB_EXT_ADDRESS_DST          6
#define SADB_EXT_ADDRESS_PROXY        7
#define SADB_EXT_KEY_AUTH             8
#define SADB_EXT_KEY_ENCRYPT          9
#define SADB_EXT_IDENTITY_SRC         10
#define SADB_EXT_IDENTITY_DST         11
#define SADB_EXT_SENSITIVITY          12
#define SADB_EXT_PROPOSAL             13
#define SADB_EXT_SUPPORTED_AUTH       14
#define SADB_EXT_SUPPORTED_ENCRYPT    15
#define SADB_EXT_SPIRANGE             16
#define SADB_X_EXT_KMPRIVATE          17
#define SADB_EXT_MAX                  17
#define SADB_SATYPE_UNSPEC    0
#define SADB_SATYPE_AH        2
#define SADB_SATYPE_ESP       3
#define SADB_SATYPE_RSVP      5
#define SADB_SATYPE_OSPFV2    6
#define SADB_SATYPE_RIPV2     7
#define SADB_SATYPE_MIP       8
#define SADB_SATYPE_MAX       8

#define SADB_SASTATE_LARVAL   0
#define SADB_SASTATE_MATURE   1
#define SADB_SASTATE_DYING    2
#define SADB_SASTATE_DEAD     3
#define SADB_SASTATE_MAX      3

#define SADB_SAFLAGS_PFS      1

#define SADB_AALG_NONE        0
#define SADB_AALG_MD5HMAC     2
#define SADB_AALG_SHA1HMAC    3

#define SADB_AALG_MAX         3

#define SADB_EALG_NONE        0
#define SADB_EALG_DESCBC      2
#define SADB_EALG_3DESCBC     3
#define SADB_EALG_NULL        11
#define SADB_EALG_MAX         11

#define SADB_IDENTTYPE_RESERVED   0
#define SADB_IDENTTYPE_PREFIX     1
#define SADB_IDENTTYPE_FQDN       2
#define SADB_IDENTTYPE_USERFQDN   3
#define SADB_IDENTTYPE_MAX        3

#define SADB_KEY_FLAGS_MAX 0
#endif /* __PFKEY_V2_H */
